// TC-003: Create with valid data (including Facility)
async function TC003() {
  const [id, title] = ['TC-003', 'Create a new Event Type with valid data'];
  const browser = await launch();
  try {
    const page = await setupPage(browser, ET_URL);
    await waitForGrid(page);
    await page.click('#setup-grid-add-button');
    await page.waitForTimeout(3000);

    const nameInput = page.locator('input.event-type-name');
    await nameInput.waitFor({ state: 'visible', timeout: 8000 });
    const uniqueName = 'TestEventType_Auto';
    await nameInput.fill(uniqueName);
    await page.waitForTimeout(500);

    // Select facility
    await selectFacility(page, 'QA_Facilities');

    // Track API responses
    let saveSuccess = false;
    const savedProm = page.waitForResponse(r =>
      (r.url().includes('eventType') || r.url().includes('addEventType') || r.url().includes('saveEventType')) &&
      r.status() < 400, { timeout: 10000 }
    ).then(() => { saveSuccess = true; }).catch(() => {});

    await page.click('button.top_right_save');
    await savedProm;
    await page.waitForTimeout(5000);

    const text = await page.evaluate(() => document.body.innerText);
    const pass = text.includes(uniqueName) || text.toLowerCase().includes('success') || text.toLowerCase().includes('saved') || saveSuccess;
    record(id, title, pass ? 'PASS' : 'FAIL', pass ? `Created: ${uniqueName}` : 'Creation not confirmed', await shot(page, id));
  } catch (e) { record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`)); }
  finally { await browser.close(); }
}

