// TC-014: Search no results
async function TC014() {
  const [id, title] = ['TC-014', 'Search with no matching term shows empty state'];
  const browser = await launch();
  try {
    const page = await setupPage(browser, ET_URL);
    await waitForGrid(page);
    const searchInput = page.locator('#setup-header-grid-quick-search');
    await searchInput.waitFor({ state: 'visible', timeout: 8000 });
    await searchInput.fill('XYZNONEXISTENT999');
    await page.waitForTimeout(3000);
    // Get the visible row count from AG Grid
    const visibleRows = await page.evaluate(() => {
      return Array.from(document.querySelectorAll('.ag-row')).filter(r => {
        const s = window.getComputedStyle(r);
        return s.display !== 'none' && s.visibility !== 'hidden';
      }).length;
    });
    const gridBodyText = await page.evaluate(() => {
      const container = document.querySelector('.ag-center-cols-container');
      return container ? container.innerText.trim() : '';
    });
    const pass = visibleRows === 0 || !gridBodyText.includes('24/7 Mode');
    record(id, title, pass ? 'PASS' : 'FAIL',
      `Visible rows: ${visibleRows}. Grid text includes 24/7 Mode: ${gridBodyText.includes('24/7 Mode')}`, await shot(page, id));
  } catch (e) { record(id, title, 'FAIL', e.message, path.join(SCREENSHOTS_DIR, `${id}.png`)); }
  finally { await browser.close(); }
}

